SELECT t1.id, t1.parent_id, t1.name, t1.type, t1.icon, t1.sort_order FROM jz_categories t1 WHERE t1.is_deleted = 0
AND (t1.user_id = #{queryParams.userId} OR t1.user_id = 0)
AND t1.name LIKE CONCAT('%', #{queryParams.name}, '%')
AND t1.type = #{queryParams.type}
AND t1.parent_id = #{queryParams.parentId}
ORDER BY t1.sort_order ASC, t1.id ASC

